INSERT INTO "public"."site_content" ("id", "lang", "content", "created_at", "updated_at") VALUES ('2de934dd-3dcc-464c-97be-6793a75d4fd6', 'en', '{"how":{"items":[{"id":"political","body":"We work within real political, institutional, and fiscal constraints.","title":"Political Reality"},{"id":"evidence","body":"We combine data, territorial analysis, and operational insight to prioritize action.","title":"Evidence & Intelligence"},{"id":"capacity","body":"We help institutions coordinate actors, strengthen execution, and sustain implementation over time.","title":"Implementation Capacity"}],"title":"How we work"},"nav":{"cta":"Contact","how":"How we work","team":"Team","what":"What we do","areas":"Areas","contact":"Contact","network":"Networks & Collaboration","solutions":"Solutions"},"hero":{"cta":"Schedule a Conversation","body":"Contextual works with governments, multilaterals, and private sector actors to translate strategic priorities into implementable action across security, justice, urban governance, and institutional delivery.","body2":"We help institutions and investors reduce operational risk, strengthen implementation capacity, and navigate complex political and territorial environments.","headline":"Designing and enabling solutions to complex public problems."},"team":{"title":"Team","members":[{"id":"enrique","bio":"Enrique Betancourt is a public policy, public innovation, and urban governance strategist with experience in security, justice, and institutional reform across Latin America. He previously served as Executive Director of Mexico’s National Center for Crime Prevention and worked within the Presidential Delivery Unit of the Government of Mexico. He holds a Master in Urban Design from Harvard University.","name":"Enrique Betancourt","role":"Co-Founder"},{"id":"jairo","bio":"Jairo García Guerrero is a senior security expert with more than 25 years of experience in citizen security, justice, and defense policy in Colombia and Ecuador. He has held senior leadership positions including Secretary of Security for Bogotá, Secretary of Security and Justice for Cali, and Vice Minister of Strategy and Planning at Colombia’s Ministry of Defense. He studied Political Science and Government at Universidad de los Andes.","name":"Jairo García Guerrero","role":"Co-Founder"},{"id":"flavia","bio":"Flávia Carbonari is an international development and citizen security specialist with experience advising governments and global institutions across Latin America and Africa. She has worked with the World Bank, Inter-American Development Bank, and CAF on violence prevention, gender, and social inclusion. She holds a Master’s degree from Georgetown University.","name":"Flávia Carbonari","role":"Specialist"},{"id":"michel","bio":"Michel Camacho is a public policy and criminal justice expert specializing in citizen security, rule of law, and institutional reform in the Caribbean. He has advised the Inter-American Development Bank, USAID, and justice institutions on police reform and organized crime. He holds an LL.M. from Georgetown University as a Fulbright Scholar.","name":"Michel Camacho","role":"Expert"}]},"what":{"items":[{"id":"security","body":"We support governments and institutions in the design and implementation of citizen security, justice, and violence prevention strategies.","title":"Security & Justice"},{"id":"urban","body":"We help cities and institutions coordinate complex urban challenges through integrated and territorially grounded approaches.","title":"Urban Governance"},{"id":"delivery","body":"We design implementation systems, coordination mechanisms, and strategic follow-up structures that help organizations execute priorities under real-world constraints.","title":"Institutional Delivery"},{"id":"innovation","body":"We help organizations and private sector actors navigate operational, institutional, and territorial complexity to strengthen decision-making and reduce risk.","title":"Public Innovation & Risk Advisory"}],"title":"What we do"},"areas":{"items":["Urban violence and citizen security","Prison and correctional systems","Interinstitutional coordination","Organized crime and territorial governance","Violence prevention","Urban management and public space","Institutional reform","Public innovation and implementation systems"],"title":"Selected Areas of Work"},"footer":{"site":"itscontextual.com","email":"hello@itscontextual.com","location":"Washington, DC"},"contact":{"cta":"Submit","title":"Contact","fields":{"name":"Name","email":"Email","message":"Message","surname":"Surname"},"subtitle":"We will contact you as soon as possible"},"network":{"body":"Contextual collaborates with governments, multilaterals, universities, think tanks, and private sector actors across Latin America and beyond.","label":"Selected networks and collaborations include:","title":"Networks & Collaboration"},"solutions":{"items":[{"id":"clinics","body":"Intensive strategic work sessions designed to align decision-makers, institutions, and operational priorities around complex challenges.","title":"Executive Clinics"},{"id":"units","body":"We design and support strategic follow-up structures that help institutions coordinate, monitor, and sustain implementation priorities.","title":"Delivery Units"},{"id":"roadmaps","body":"We translate political, institutional, and operational priorities into concrete implementation pathways.","title":"Strategic Implementation Roadmaps"},{"id":"risk","body":"We help organizations and investors understand and reduce operational, territorial, and institutional risks in complex environments.","title":"Risk & Context Advisory"}],"title":"Solutions"}}', '2026-06-28 21:49:38.922875+00', '2026-06-28 22:14:21.471083+00'), ('b0d4b2f8-dd1c-423d-8902-f60492901b69', 'es', '{"how":{"items":[{"id":"political","body":"Trabajamos dentro de restricciones políticas, institucionales y fiscales reales.","title":"Realidad Política"},{"id":"evidence","body":"Combinamos datos, análisis territorial y conocimiento operativo para priorizar acción.","title":"Evidencia e Inteligencia"},{"id":"capacity","body":"Ayudamos a instituciones a coordinar actores, fortalecer ejecución y sostener implementación en el tiempo.","title":"Capacidad de Implementación"}],"title":"Cómo trabajamos"},"nav":{"cta":"Contactar","how":"Cómo trabajamos","team":"Equipo","what":"Qué hacemos","areas":"Áreas","contact":"Contacto","network":"Redes/Colaboraciones","solutions":"Soluciones"},"hero":{"cta":"Agendar conversación","body":"Contextual trabaja con gobiernos, organismos multilaterales y actores del sector privado para traducir prioridades estratégicas en acción implementable en seguridad, justicia, gobernanza urbana e implementación institucional.","body2":"Ayudamos a instituciones e inversionistas a reducir riesgos operativos, fortalecer capacidades de implementación y navegar entornos políticos y \\nterritoriales\\ncomplejos.","headline":"Diseñamos y habilitamos soluciones para problemas públicos complejos."},"team":{"title":"Equipo","members":[{"id":"enrique","bio":"Enrique Betancourt es un estratega en políticas públicas, innovación pública y gobernanza urbana con experiencia en seguridad, justicia y fortalecimiento institucional en América Latina. Fue titular del Centro Nacional de Prevención del Delito del Gobierno de México y formó parte de la Unidad de la Oficina de la Presidencia encargada del seguimiento de prioridades estratégicas e implementación gubernamental. Cuenta con una Maestría en Urbanismo por Harvard University.","name":"Enrique Betancourt","role":"Co-Fundador"},{"id":"jairo","bio":"Jairo García Guerrero es un experto senior en seguridad con más de 25 años de experiencia en seguridad ciudadana, justicia y defensa en Colombia y Ecuador. Ha ocupado cargos de alta dirección como Secretario de Seguridad de Bogotá, Secretario de Seguridad y Justicia de Cali y Viceministro de Estrategia y Planeación del Ministerio de Defensa de Colombia. Estudió Ciencia Política y Gobierno en Universidad de los Andes.","name":"Jairo García Guerrero","role":"Co-Fundador"},{"id":"flavia","bio":"Especialista en desarrollo internacional y seguridad ciudadana con experiencia asesorando a gobiernos y organismos internacionales en América Latina y África. Ha trabajado con el World Bank, el Inter-American Development Bank y CAF en prevención de violencia, género e inclusión social. Cuenta con una Maestría por Georgetown University.","name":"Flávia Carbonari","role":"Especialista"},{"id":"michel","bio":"Experto en políticas públicas y justicia penal especializado en seguridad ciudadana, estado de derecho y fortalecimiento institucional en el Caribe. Ha asesorado al Inter-American Development Bank, USAID y a instituciones del sector justicia en reforma policial y crimen organizado. Cuenta con una Maestría en Regulación Financiera por Georgetown University como Fulbright Scholar.","name":"Michel Camacho","role":"Experto"}]},"what":{"items":[{"id":"security","body":"Apoyamos a gobiernos e instituciones en el diseño e implementación de estrategias de seguridad ciudadana, justicia y prevención de violencia.","title":"Seguridad y Justicia"},{"id":"urban","body":"Ayudamos a ciudades e instituciones a coordinar desafíos urbanos complejos mediante enfoques integrados y territorialmente focalizados.","title":"Gobernanza Urbana"},{"id":"delivery","body":"Diseñamos sistemas de implementación, mecanismos de coordinación y estructuras de seguimiento estratégico que ayudan a ejecutar prioridades bajo restricciones reales.","title":"Implementación Institucional"},{"id":"innovation","body":"Ayudamos a organizaciones y actores del sector privado a navegar complejidad operativa, institucional y territorial para fortalecer decisiones y reducir riesgos.","title":"Innovación Pública y Risk Advisory"}],"title":"Qué hacemos"},"areas":{"items":["Violencia urbana y seguridad ciudadana","Sistemas penitenciarios y correccionales","Coordinación interinstitucional","Crimen organizado y gobernanza territorial","Prevención de violencia","Gestión urbana y espacio público","Reforma institucional","Innovación pública y sistemas de implementación"],"title":"Áreas de Trabajo"},"footer":{"site":"itscontextual.com","email":"hello@itscontextual.com","location":"Washington, DC"},"contact":{"cta":"Enviar","title":"Contacto","fields":{"name":"Nombre","email":"Correo electrónico","message":"Mensaje","surname":"Apellido"},"subtitle":"Nos comunicaremos con usted a la brevedad"},"network":{"body":"Contextual colabora con gobiernos, organismos multilaterales, universidades, think tanks y actores del sector privado en América Latina y otras regiones.","label":"Algunas redes y colaboraciones incluyen:","title":"Redes y Colaboraciones"},"solutions":{"items":[{"id":"clinics","body":"Espacios estratégicos de trabajo intensivo diseñados para alinear tomadores de decisión, instituciones y prioridades operativas alrededor de desafíos complejos.","title":"Clínicas Ejecutivas"},{"id":"units","body":"Diseñamos y acompañamos estructuras de seguimiento estratégico que ayudan a coordinar, monitorear y sostener prioridades de implementación.","title":"Delivery Units"},{"id":"roadmaps","body":"Traducimos prioridades políticas, institucionales y operativas en rutas concretas de implementación.","title":"Hojas de Ruta para la Implementación Estratégica"},{"id":"risk","body":"Ayudamos a organizaciones e inversionistas a entender y reducir riesgos operativos, territoriales e institucionales en entornos complejos.","title":"Risk & Context Advisory"}],"title":"Soluciones"}}', '2026-06-28 21:48:43.11152+00', '2026-06-29 01:57:03.547655+00');